CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_adrprovider]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_adrprovider]
	(
		[apuk_adrproviderid],
		[apuk_hasmessage],
		[apuk_messagetext],
		[apuk_name],
		[apuk_showforfirmregulation],
		[apuk_showforvrlist],
		[apuk_validfrom],
		[apuk_validto],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_adrproviderid],
		stg.[apuk_hasmessage],
		stg.[apuk_messagetext],
		stg.[apuk_name],
		stg.[apuk_showforfirmregulation],
		stg.[apuk_showforvrlist],
		stg.[apuk_validfrom],
		stg.[apuk_validto],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_adrprovider] stg
		LEFT JOIN [synapse_ce].[apuk_adrprovider] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
